#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int length;
    cin >> length;
    string str;
    cin >> str;
    bool inParentheses = false;
    string segmentBuilder;
    int maxOutsideSize = 0;
    int insideWordsCount = 0;
    for (int i = 0; i < length; i++) {
        char ch = str[i];
        if (ch == '(') {
            if (!inParentheses) {
                vector<string> outsideParts;
                stringstream ss(segmentBuilder);
                string part;
                while (getline(ss, part, '_')) {
                    outsideParts.push_back(part);
                }
                for (const auto& p : outsideParts) {
                    maxOutsideSize = max(maxOutsideSize, (int)p.length());
                }
            }
            inParentheses = true;
            segmentBuilder.clear();
        } else if (ch == ')') {
            inParentheses = false;
            vector<string> insideParts;
            stringstream ss(segmentBuilder);
            string part;
            while (getline(ss, part, '_')) {
                insideParts.push_back(part);
            }
            for (const auto& p : insideParts) {
                if (!p.empty()) {
                    insideWordsCount++;
                }
            }
            segmentBuilder.clear();
        } else {
            segmentBuilder += ch;
        }
    }
    vector<string> outsideRemaining;
    stringstream ss(segmentBuilder);
    string part;
    while (getline(ss, part, '_')) {
        outsideRemaining.push_back(part);
    }
    for (const auto& p : outsideRemaining) {
        maxOutsideSize = max(maxOutsideSize, (int)p.length());
    }
    cout << maxOutsideSize << " " << insideWordsCount << "\n";
    return 0;
}
